/* ---- chess.js ---- */
﻿/* ==========================================================================
 * 鲸娘棋局 · 规则核心（无外部依赖）
 * 0x00 = a8 … 0x3f = h1；小写为黑（鲸娘），大写为白（主人）。
 * ========================================================================== */
const WhaleChessRules = (() => {
  const FILES = 'abcdefgh';
  const START_FEN = 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1';
  const VAL = { p: 100, n: 320, b: 330, r: 500, q: 900, k: 0 };
  const MATE = 100000;
  const INF = 1000000;

  const isWhitePiece = (ch) => ch >= 'A' && ch <= 'Z';
  const colorOf = (ch) => (isWhitePiece(ch) ? 'w' : 'b');
  const typeOf = (ch) => ch.toLowerCase();
  const other = (c) => (c === 'w' ? 'b' : 'w');
  const onBoard = (f, r) => f >= 0 && f < 8 && r >= 0 && r < 8;
  const sqIndex = (f, r) => r * 8 + f;
  const fileOf = (sq) => sq & 7;
  const rowOf = (sq) => sq >> 3;
  const sqName = (sq) => FILES[fileOf(sq)] + String(8 - rowOf(sq));
  const nameToSq = (name) => {
    const f = FILES.indexOf(name[0]);
    const r = 8 - Number(name[1]);
    return sqIndex(f, r);
  };

  const KNIGHT_D = [[1, 2], [2, 1], [2, -1], [1, -2], [-1, -2], [-2, -1], [-2, 1], [-1, 2]];
  const BISHOP_D = [[1, 1], [1, -1], [-1, 1], [-1, -1]];
  const ROOK_D = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const KING_D = BISHOP_D.concat(ROOK_D);

  /* ---------------------------------------------------------------- FEN */

  function parseFEN(fen) {
    const parts = (fen || START_FEN).trim().split(/\s+/);
    const board = new Array(64).fill('');
    let sq = 0;
    for (const ch of parts[0]) {
      if (ch === '/') continue;
      if (/\d/.test(ch)) sq += Number(ch);
      else board[sq++] = ch;
    }
    const castle = { K: false, Q: false, k: false, q: false };
    for (const ch of parts[2] || '-') {
      if (ch in castle) castle[ch] = true;
    }
    return {
      board,
      turn: parts[1] === 'b' ? 'b' : 'w',
      castle,
      ep: parts[3] && parts[3] !== '-' ? nameToSq(parts[3]) : -1,
      halfmove: Number(parts[4] || 0),
      fullmove: Number(parts[5] || 1),
    };
  }

  function toFEN(state) {
    let out = '';
    for (let r = 0; r < 8; r++) {
      let empty = 0;
      for (let f = 0; f < 8; f++) {
        const p = state.board[r * 8 + f];
        if (!p) empty++;
        else {
          if (empty) { out += empty; empty = 0; }
          out += p;
        }
      }
      if (empty) out += empty;
      if (r < 7) out += '/';
    }
    const c = state.castle;
    const castle = (c.K ? 'K' : '') + (c.Q ? 'Q' : '') + (c.k ? 'k' : '') + (c.q ? 'q' : '');
    return [
      out,
      state.turn,
      castle || '-',
      state.ep >= 0 ? sqName(state.ep) : '-',
      state.halfmove || 0,
      state.fullmove || 1,
    ].join(' ');
  }

  const clone = (s) => ({
    board: s.board.slice(),
    turn: s.turn,
    castle: { ...s.castle },
    ep: s.ep,
    halfmove: s.halfmove,
    fullmove: s.fullmove,
  });

  function kingSquare(state, color) {
    const target = color === 'w' ? 'K' : 'k';
    for (let i = 0; i < 64; i++) if (state.board[i] === target) return i;
    return -1;
  }

  /* ------------------------------------------------------- attack tests */

  function squareAttacked(state, sq, byColor) {
    const f = fileOf(sq);
    const r = rowOf(sq);
    const b = state.board;

    // pawns
    const pawnRow = byColor === 'w' ? r + 1 : r - 1;
    const pawn = byColor === 'w' ? 'P' : 'p';
    if (pawnRow >= 0 && pawnRow < 8) {
      if (f > 0 && b[sqIndex(f - 1, pawnRow)] === pawn) return true;
      if (f < 7 && b[sqIndex(f + 1, pawnRow)] === pawn) return true;
    }
    // knights
    const knight = byColor === 'w' ? 'N' : 'n';
    for (const [df, dr] of KNIGHT_D) {
      const nf = f + df;
      const nr = r + dr;
      if (onBoard(nf, nr) && b[sqIndex(nf, nr)] === knight) return true;
    }
    // king
    const king = byColor === 'w' ? 'K' : 'k';
    for (const [df, dr] of KING_D) {
      const nf = f + df;
      const nr = r + dr;
      if (onBoard(nf, nr) && b[sqIndex(nf, nr)] === king) return true;
    }
    // sliders
    const rookish = byColor === 'w' ? ['R', 'Q'] : ['r', 'q'];
    for (const [df, dr] of ROOK_D) {
      let nf = f + df;
      let nr = r + dr;
      while (onBoard(nf, nr)) {
        const p = b[sqIndex(nf, nr)];
        if (p) {
          if (rookish.includes(p)) return true;
          break;
        }
        nf += df; nr += dr;
      }
    }
    const bishopish = byColor === 'w' ? ['B', 'Q'] : ['b', 'q'];
    for (const [df, dr] of BISHOP_D) {
      let nf = f + df;
      let nr = r + dr;
      while (onBoard(nf, nr)) {
        const p = b[sqIndex(nf, nr)];
        if (p) {
          if (bishopish.includes(p)) return true;
          break;
        }
        nf += df; nr += dr;
      }
    }
    return false;
  }

  function inCheck(state, color) {
    const k = kingSquare(state, color);
    if (k < 0) return false;
    return squareAttacked(state, k, other(color));
  }

  /* ----------------------------------------------------------- movegen */

  function pushPawnMoves(out, state, from, to, color, flags) {
    const promoRow = color === 'w' ? 0 : 7;
    if (rowOf(to) === promoRow) {
      for (const promo of ['q', 'r', 'b', 'n']) {
        out.push({ from, to, piece: color === 'w' ? 'P' : 'p', cap: state.board[to] || '', promo, flag: flags || '' });
      }
    } else {
      out.push({ from, to, piece: color === 'w' ? 'P' : 'p', cap: state.board[to] || '', promo: '', flag: flags || '' });
    }
  }

  function pseudoMoves(state) {
    const out = [];
    const b = state.board;
    const turn = state.turn;
    for (let from = 0; from < 64; from++) {
      const p = b[from];
      if (!p || colorOf(p) !== turn) continue;
      const type = typeOf(p);
      const f = fileOf(from);
      const r = rowOf(from);

      if (type === 'p') {
        const dir = turn === 'w' ? -1 : 1;
        const startRow = turn === 'w' ? 6 : 1;
        const oneR = r + dir;
        if (onBoard(f, oneR) && !b[sqIndex(f, oneR)]) {
          pushPawnMoves(out, state, from, sqIndex(f, oneR), turn, '');
          const twoR = r + dir * 2;
          if (r === startRow && !b[sqIndex(f, twoR)]) {
            out.push({ from, to: sqIndex(f, twoR), piece: p, cap: '', promo: '', flag: 'double' });
          }
        }
        for (const df of [-1, 1]) {
          const nf = f + df;
          if (!onBoard(nf, oneR)) continue;
          const to = sqIndex(nf, oneR);
          const target = b[to];
          if (target && colorOf(target) !== turn) {
            pushPawnMoves(out, state, from, to, turn, '');
          } else if (!target && state.ep === to) {
            out.push({ from, to, piece: p, cap: turn === 'w' ? 'p' : 'P', promo: '', flag: 'ep' });
          }
        }
      } else if (type === 'n' || type === 'k') {
        const dirs = type === 'n' ? KNIGHT_D : KING_D;
        for (const [df, dr] of dirs) {
          const nf = f + df;
          const nr = r + dr;
          if (!onBoard(nf, nr)) continue;
          const to = sqIndex(nf, nr);
          const target = b[to];
          if (target && colorOf(target) === turn) continue;
          out.push({ from, to, piece: p, cap: target || '', promo: '', flag: '' });
        }
      } else {
        const dirs = type === 'b' ? BISHOP_D : type === 'r' ? ROOK_D : KING_D;
        for (const [df, dr] of dirs) {
          let nf = f + df;
          let nr = r + dr;
          while (onBoard(nf, nr)) {
            const to = sqIndex(nf, nr);
            const target = b[to];
            if (target && colorOf(target) === turn) break;
            out.push({ from, to, piece: p, cap: target || '', promo: '', flag: '' });
            if (target) break;
            nf += df; nr += dr;
          }
        }
      }
    }

    // castling
    const kingFrom = turn === 'w' ? 60 : 4;
    if (b[kingFrom] === (turn === 'w' ? 'K' : 'k')) {
      const kingSide = turn === 'w' ? state.castle.K : state.castle.k;
      const queenSide = turn === 'w' ? state.castle.Q : state.castle.q;
      const rookKing = turn === 'w' ? 'R' : 'r';
      if (kingSide && b[turn === 'w' ? 63 : 7] === rookKing
        && !b[turn === 'w' ? 61 : 5] && !b[turn === 'w' ? 62 : 6]
        && !squareAttacked(state, kingFrom, other(turn))
        && !squareAttacked(state, turn === 'w' ? 61 : 5, other(turn))
        && !squareAttacked(state, turn === 'w' ? 62 : 6, other(turn))) {
        out.push({ from: kingFrom, to: turn === 'w' ? 62 : 6, piece: b[kingFrom], cap: '', promo: '', flag: 'castleK' });
      }
      if (queenSide && b[turn === 'w' ? 56 : 0] === rookKing
        && !b[turn === 'w' ? 59 : 3] && !b[turn === 'w' ? 58 : 2] && !b[turn === 'w' ? 57 : 1]
        && !squareAttacked(state, kingFrom, other(turn))
        && !squareAttacked(state, turn === 'w' ? 59 : 3, other(turn))
        && !squareAttacked(state, turn === 'w' ? 58 : 2, other(turn))) {
        out.push({ from: kingFrom, to: turn === 'w' ? 58 : 2, piece: b[kingFrom], cap: '', promo: '', flag: 'castleQ' });
      }
    }
    return out;
  }

  function applyMove(state, m) {
    const s = clone(state);
    const b = s.board;
    const color = colorOf(m.piece);
    b[m.to] = m.promo ? (color === 'w' ? m.promo.toUpperCase() : m.promo) : m.piece;
    b[m.from] = '';

    if (m.flag === 'ep') {
      const capturedSq = color === 'w' ? m.to + 8 : m.to - 8;
      b[capturedSq] = '';
    }
    if (m.flag === 'castleK') {
      const rf = color === 'w' ? 63 : 7;
      const rt = color === 'w' ? 61 : 5;
      b[rt] = b[rf]; b[rf] = '';
    }
    if (m.flag === 'castleQ') {
      const rf = color === 'w' ? 56 : 0;
      const rt = color === 'w' ? 59 : 3;
      b[rt] = b[rf]; b[rf] = '';
    }

    // castling rights
    const c = s.castle;
    if (m.piece === 'K') { c.K = false; c.Q = false; }
    if (m.piece === 'k') { c.k = false; c.q = false; }
    if (m.from === 63 || m.to === 63) c.K = false;
    if (m.from === 56 || m.to === 56) c.Q = false;
    if (m.from === 7 || m.to === 7) c.k = false;
    if (m.from === 0 || m.to === 0) c.q = false;

    s.ep = m.flag === 'double' ? (m.from + m.to) / 2 : -1;
    const isCapture = Boolean(m.cap) || m.flag === 'ep';
    s.halfmove = (typeOf(m.piece) === 'p' || isCapture) ? 0 : (s.halfmove || 0) + 1;
    if (state.turn === 'b') s.fullmove = (state.fullmove || 1) + 1;
    s.turn = other(state.turn);
    return s;
  }

  function legalMoves(state) {
    const turn = state.turn;
    const out = [];
    for (const m of pseudoMoves(state)) {
      const next = applyMove(state, m);
      if (!inCheck(next, turn)) out.push(m);
    }
    return out;
  }

  /* --------------------------------------------------------------- SAN */

  const PIECE_LETTER = { n: 'N', b: 'B', r: 'R', q: 'Q', k: 'K', p: '' };

  function sanOf(state, m, moves) {
    const all = moves || legalMoves(state);
    const color = state.turn;
    let san;
    if (m.flag === 'castleK') san = 'O-O';
    else if (m.flag === 'castleQ') san = 'O-O-O';
    else {
      const type = typeOf(m.piece);
      const target = sqName(m.to);
      const capture = Boolean(m.cap) || m.flag === 'ep';
      if (type === 'p') {
        san = capture ? FILES[fileOf(m.from)] + 'x' + target : target;
        if (m.promo) san += '=' + m.promo.toUpperCase();
      } else {
        let disamb = '';
        const twins = all.filter((o) => o.to === m.to && o.from !== m.from && typeOf(o.piece) === type
          && colorOf(o.piece) === color);
        if (twins.length) {
          const sameFile = twins.some((o) => fileOf(o.from) === fileOf(m.from));
          const sameRank = twins.some((o) => rowOf(o.from) === rowOf(m.from));
          if (!sameFile) disamb = FILES[fileOf(m.from)];
          else if (!sameRank) disamb = String(8 - rowOf(m.from));
          else disamb = FILES[fileOf(m.from)] + String(8 - rowOf(m.from));
        }
        san = PIECE_LETTER[type] + disamb + (capture ? 'x' : '') + target;
      }
    }
    const next = applyMove(state, m);
    if (inCheck(next, next.turn)) {
      san += legalMoves(next).length === 0 ? '#' : '+';
    }
    return san;
  }

  function findMoveBySAN(state, san) {
    const needle = String(san || '').replace(/[+#!?]+$/, '');
    const moves = legalMoves(state);
    for (const m of moves) {
      if (sanOf(state, m, moves).replace(/[+#]+$/, '') === needle) return m;
    }
    return null;
  }

  /* ------------------------------------------------------------- status */

  function materialCount(state) {
    const count = { w: 0, b: 0 };
    const kinds = { w: {}, b: {} };
    for (const p of state.board) {
      if (!p) continue;
      const c = colorOf(p);
      const t = typeOf(p);
      count[c] += VAL[t];
      kinds[c][t] = (kinds[c][t] || 0) + 1;
    }
    return { count, kinds };
  }

  function insufficientMaterial(state) {
    const { kinds } = materialCount(state);
    const list = (c) => Object.keys(kinds[c]).filter((t) => kinds[c][t] > 0);
    const w = list('w');
    const b = list('b');
    const bare = (arr) => arr.every((t) => t === 'k');
    const minor = (arr) => arr.length <= 2 && arr.every((t) => 'kn'.includes(t));
    if (bare(w) && bare(b)) return true;
    if (bare(w) && minor(b)) return true;
    if (bare(b) && minor(w)) return true;
    if (w.length === 2 && b.length === 2 && w.includes('b') && b.includes('b')) {
      // opposite-colour bishops is a draw; same colour needs square check — approximate false
      const light = (state.board.filter((p, i) => p === 'B' && (fileOf(i) + rowOf(i)) % 2 === 0).length);
      const dark = (state.board.filter((p, i) => p === 'B' && (fileOf(i) + rowOf(i)) % 2 === 1).length);
      if (light && dark) return false;
    }
    return false;
  }

  function status(state) {
    const moves = legalMoves(state);
    if (moves.length === 0) {
      if (inCheck(state, state.turn)) {
        return { over: true, result: 'checkmate', winner: other(state.turn), reason: 'checkmate' };
      }
      return { over: true, result: 'stalemate', winner: null, reason: 'stalemate' };
    }
    if (state.halfmove >= 100) return { over: true, result: 'draw', winner: null, reason: 'fifty' };
    if (insufficientMaterial(state)) return { over: true, result: 'draw', winner: null, reason: 'material' };
    return { over: false, result: null, winner: null, reason: inCheck(state, state.turn) ? 'check' : '' };
  }

  /* ------------------------------------------------------------ attacks */

  function attacksFrom(state, from) {
    const p = state.board[from];
    if (!p) return [];
    const out = [];
    const b = state.board;
    const f = fileOf(from);
    const r = rowOf(from);
    const type = typeOf(p);
    const own = colorOf(p);
    if (type === 'p') {
      const dir = own === 'w' ? -1 : 1;
      for (const df of [-1, 1]) {
        const nf = f + df;
        const nr = r + dir;
        if (onBoard(nf, nr)) out.push(sqIndex(nf, nr));
      }
      return out;
    }
    if (type === 'n' || type === 'k') {
      for (const [df, dr] of type === 'n' ? KNIGHT_D : KING_D) {
        const nf = f + df;
        const nr = r + dr;
        if (onBoard(nf, nr)) out.push(sqIndex(nf, nr));
      }
      return out;
    }
    const dirs = type === 'b' ? BISHOP_D : type === 'r' ? ROOK_D : KING_D;
    for (const [df, dr] of dirs) {
      let nf = f + df;
      let nr = r + dr;
      while (onBoard(nf, nr)) {
        const to = sqIndex(nf, nr);
        out.push(to);
        if (b[to]) break;
        nf += df; nr += dr;
      }
    }
    return out;
  }

  function enemyKingSquare(state, color) {
    return kingSquare(state, other(color));
  }

  /* ---------------------------------------------------------- evaluate */

  const PST = {
    p: [
      0, 0, 0, 0, 0, 0, 0, 0,
      50, 50, 50, 50, 50, 50, 50, 50,
      10, 10, 20, 30, 30, 20, 10, 10,
      5, 5, 10, 27, 27, 10, 5, 5,
      0, 0, 0, 25, 25, 0, 0, 0,
      5, -5, -10, 0, 0, -10, -5, 5,
      5, 10, 10, -25, -25, 10, 10, 5,
      0, 0, 0, 0, 0, 0, 0, 0,
    ],
    n: [
      -50, -40, -30, -30, -30, -30, -40, -50,
      -40, -20, 0, 0, 0, 0, -20, -40,
      -30, 0, 10, 15, 15, 10, 0, -30,
      -30, 5, 15, 20, 20, 15, 5, -30,
      -30, 0, 15, 20, 20, 15, 0, -30,
      -30, 5, 10, 15, 15, 10, 5, -30,
      -40, -20, 0, 5, 5, 0, -20, -40,
      -50, -40, -30, -30, -30, -30, -40, -50,
    ],
    b: [
      -20, -10, -10, -10, -10, -10, -10, -20,
      -10, 0, 0, 0, 0, 0, 0, -10,
      -10, 0, 5, 10, 10, 5, 0, -10,
      -10, 5, 5, 10, 10, 5, 5, -10,
      -10, 0, 10, 10, 10, 10, 0, -10,
      -10, 10, 10, 10, 10, 10, 10, -10,
      -10, 5, 0, 0, 0, 0, 5, -10,
      -20, -10, -10, -10, -10, -10, -10, -20,
    ],
    r: [
      0, 0, 0, 0, 0, 0, 0, 0,
      5, 10, 10, 10, 10, 10, 10, 5,
      -5, 0, 0, 0, 0, 0, 0, -5,
      -5, 0, 0, 0, 0, 0, 0, -5,
      -5, 0, 0, 0, 0, 0, 0, -5,
      -5, 0, 0, 0, 0, 0, 0, -5,
      -5, 0, 0, 0, 0, 0, 0, -5,
      0, 0, 0, 5, 5, 0, 0, 0,
    ],
    q: [
      -20, -10, -10, -5, -5, -10, -10, -20,
      -10, 0, 0, 0, 0, 0, 0, -10,
      -10, 0, 5, 5, 5, 5, 0, -10,
      -5, 0, 5, 5, 5, 5, 0, -5,
      0, 0, 5, 5, 5, 5, 0, -5,
      -10, 5, 5, 5, 5, 5, 0, -10,
      -10, 0, 5, 0, 0, 0, 0, -10,
      -20, -10, -10, -5, -5, -10, -10, -20,
    ],
    k: [
      -30, -40, -40, -50, -50, -40, -40, -30,
      -30, -40, -40, -50, -50, -40, -40, -30,
      -30, -40, -40, -50, -50, -40, -40, -30,
      -30, -40, -40, -50, -50, -40, -40, -30,
      -20, -30, -30, -40, -40, -30, -30, -20,
      -10, -20, -20, -20, -20, -20, -20, -10,
      20, 20, 0, 0, 0, 0, 20, 20,
      20, 30, 10, 0, 0, 10, 30, 20,
    ],
  };

  // mirror table for black (rank flip)
  const MIRROR = (() => {
    const arr = [];
    for (let i = 0; i < 64; i++) arr.push((7 - (i >> 3)) * 8 + (i & 7));
    return arr;
  })();

  function evaluate(state) {
    const b = state.board;
    let score = 0;
    let phase = 0;
    const pawnFiles = { w: new Array(8).fill(0), b: new Array(8).fill(0) };
    const bishops = { w: 0, b: 0 };

    for (let i = 0; i < 64; i++) {
      const p = b[i];
      if (!p) continue;
      const t = typeOf(p);
      const c = colorOf(p);
      const table = PST[t];
      const idx = c === 'w' ? i : MIRROR[i];
      const sign = c === 'w' ? 1 : -1;
      score += sign * (VAL[t] + table[idx]);
      if (t === 'b') bishops[c]++;
      if (t !== 'p' && t !== 'k') phase += 1;
      if (t === 'p') pawnFiles[c][fileOf(i)]++;
    }
    if (bishops.w >= 2) score += 28;
    if (bishops.b >= 2) score -= 28;

    // doubled / isolated pawns
    let pawnStruct = 0;
    for (const c of ['w', 'b']) {
      const files = pawnFiles[c];
      for (let f = 0; f < 8; f++) {
        if (files[f] > 1) pawnStruct -= 14 * (files[f] - 1);
        if (files[f] && !(files[f - 1] || 0) && !(files[f + 1] || 0)) pawnStruct -= 12;
      }
      score += c === 'w' ? pawnStruct : -pawnStruct;
      pawnStruct = 0;
    }

    // king safety: pawn shield in front of king
    for (const c of ['w', 'b']) {
      const k = kingSquare(state, c);
      if (k < 0) continue;
      let shield = 0;
      const dir = c === 'w' ? -1 : 1;
      for (const df of [-1, 0, 1]) {
        const nf = fileOf(k) + df;
        const nr = rowOf(k) + dir;
        if (onBoard(nf, nr)) {
          const p = b[sqIndex(nf, nr)];
          if (p && typeOf(p) === 'p' && colorOf(p) === c) shield += 8;
        }
      }
      score += (c === 'w' ? 1 : -1) * shield;
    }

    // side-to-move mobility (cheap: pseudo count), without mutating the input
    const probe = { board: state.board, turn: 'w', castle: state.castle, ep: state.ep };
    probe.turn = 'w';
    const whiteMobility = pseudoMoves(probe).length;
    probe.turn = 'b';
    const blackMobility = pseudoMoves(probe).length;
    score += (whiteMobility - blackMobility) * 2;

    return score;
  }

  /* ------------------------------------------------------------ search */

  let nodes = 0;

  function moveScore(m, state) {
    let s = 0;
    if (m.cap) s += 10 * VAL[typeOf(m.cap)] - VAL[typeOf(m.piece)];
    if (m.promo) s += 800 + VAL[m.promo];
    if (m.flag === 'castleK' || m.flag === 'castleQ') s += 40;
    return s;
  }

  function orderedMoves(state, moves) {
    return moves.slice().sort((a, b) => moveScore(b, state) - moveScore(a, state));
  }

  function quiesce(state, alpha, beta, qdepth) {
    nodes++;
    const stand = evaluate(state) * (state.turn === 'w' ? 1 : -1);
    if ((qdepth || 0) >= 3) return stand;
    if (stand >= beta) return beta;
    if (stand > alpha) alpha = stand;
    const caps = orderedMoves(state, pseudoMoves(state).filter((m) => m.cap || m.promo));
    for (const m of caps) {
      const next = applyMove(state, m);
      if (inCheck(next, state.turn)) continue;
      const score = -quiesce(next, -beta, -alpha, (qdepth || 0) + 1);
      if (score >= beta) return beta;
      if (score > alpha) alpha = score;
    }
    return alpha;
  }

  function negamax(state, depth, alpha, beta) {
    nodes++;
    const moves = legalMoves(state);
    if (moves.length === 0) {
      return inCheck(state, state.turn) ? -MATE + (10 - depth) : 0;
    }
    if (depth <= 0) return quiesce(state, alpha, beta);
    for (const m of orderedMoves(state, moves)) {
      const next = applyMove(state, m);
      const score = -negamax(next, depth - 1, -beta, -alpha);
      if (score >= beta) return beta;
      if (score > alpha) alpha = score;
    }
    return alpha;
  }

  function search(state, depth) {
    nodes = 0;
    const cp = negamax(state, depth, -INF, INF);
    return { cp, nodes };
  }

  /* --------------------------------------------------- candidate ranking */

  function attackedPieces(state, from, color) {
    const targets = [];
    for (const sq of attacksFrom(state, from)) {
      const p = state.board[sq];
      if (p && colorOf(p) !== color) targets.push({ sq, p, val: VAL[typeOf(p)] });
    }
    return targets;
  }

  function moveTags(state, m) {
    const tags = [];
    const next = applyMove(state, m);
    const color = colorOf(m.piece);
    if (m.cap) tags.push('capture');
    if (m.promo) tags.push('promote');
    if (m.flag === 'castleK' || m.flag === 'castleQ') tags.push('castle');
    if (inCheck(next, next.turn)) tags.push('check');
    if (!m.cap && !m.promo && typeOf(m.piece) === 'p') tags.push('pawn');
    if (['n', 'b'].includes(typeOf(m.piece))) tags.push('develop');
    const f = fileOf(m.to);
    const r = rowOf(m.to);
    if (f >= 2 && f <= 5 && r >= 2 && r <= 5) tags.push('center');
    if (typeOf(m.piece) === 'q' && ['d', 'a'].includes(FILES[f])) tags.push('queenside');
    if (typeOf(m.piece) === 'q' && ['e', 'h'].includes(FILES[f])) tags.push('kingside');

    // fork: after the move, the piece attacks >=2 valuable enemy targets
    const targets = attackedPieces(next, m.to, color);
    if (targets.filter((t) => t.val >= 300).length >= 2) tags.push('fork');
    if (targets.some((t) => t.val >= 900)) tags.push('attackQueen');
    for (const t of targets) {
      const letter = typeOf(t.p).toUpperCase();
      if (!tags.includes('hits' + letter)) tags.push('hits' + letter);
    }

    // king pressure: attacks a square next to the enemy king
    const ek = enemyKingSquare(next, color);
    if (ek >= 0) {
      const around = KING_D.map(([df, dr]) => {
        const nf = fileOf(ek) + df;
        const nr = rowOf(ek) + dr;
        return onBoard(nf, nr) ? sqIndex(nf, nr) : -1;
      }).filter((s) => s >= 0);
      if (attacksFrom(next, m.to).some((s) => around.includes(s))) tags.push('attackKing');
    }
    if (m.cap && VAL[typeOf(m.cap)] > VAL[typeOf(m.piece)]) tags.push('winMaterial');
    if (m.flag === 'ep') tags.push('enPassant');
    return tags;
  }

  /**
   * Objective candidate list, ranked by a shallow alpha-beta score.
   * Returns move objects enriched with { san, cp, cpEval, tags, rank }.
   * cp is from the point of view of the side to move.
   */
  function rankMoves(state, depth, limit) {
    const d = Math.max(1, depth || 2);
    const moves = legalMoves(state);
    nodes = 0;
    let pool = moves;
    if (moves.length > (limit || 12)) {
      const prelim = moves.map((m) => {
        const next = applyMove(state, m);
        return { m, s: evaluate(next) * (state.turn === 'w' ? 1 : -1) };
      });
      prelim.sort((a, b) => b.s - a.s);
      pool = prelim.slice(0, limit || 12).map((x) => x.m);
    }
    const ranked = pool.map((m) => {
      const next = applyMove(state, m);
      const cp = -negamax(next, d - 1, -INF, INF);
      const evalStatic = evaluate(next) * (state.turn === 'w' ? 1 : -1);
      return { move: m, cp, cpEval: evalStatic, tags: moveTags(state, m) };
    });
    ranked.sort((a, b) => b.cp - a.cp);
    ranked.forEach((entry, i) => {
      entry.rank = i + 1;
      entry.san = sanOf(state, entry.move, moves);
      entry.uci = sqName(entry.move.from) + sqName(entry.move.to) + (entry.move.promo || '');
      entry.capture = entry.move.cap ? typeOf(entry.move.cap) : '';
      entry.piece = typeOf(entry.move.piece);
    });
    return { candidates: ranked, nodes, depth: d };
  }

  function perft(state, depth) {
    if (depth === 0) return 1;
    let total = 0;
    for (const m of legalMoves(state)) {
      total += perft(applyMove(state, m), depth - 1);
    }
    return total;
  }

  return {
    START_FEN, VAL, MATE,
    parseFEN, toFEN, clone, applyMove, legalMoves, pseudoMoves,
    inCheck, squareAttacked, kingSquare, status, insufficientMaterial,
    sanOf, findMoveBySAN, evaluate, search, rankMoves, moveTags,
    attacksFrom, sqName, nameToSq, fileOf, rowOf, other, colorOf, typeOf,
    perft,
  };
})();




